-- [curatela] secao avaliacao_funcionalidade: {{funcionalidade_abvd_grau}}, {{funcionalidade_aivd_grau}}, {{funcionalidade_atividades_criticas}}, {{funcionalidade_tipo_auxilio}}
update public.secoes set texto_automatico_template = 'Quanto à funcionalidade, apresenta [funcionalidade_abvd_grau] para as atividades básicas da vida diária e [funcionalidade_aivd_grau] de dependência para as atividades instrumentais, necessitando de [funcionalidade_tipo_auxilio] principalmente para [funcionalidade_atividades_criticas].' where id = '647490b9-ed73-511f-8f3f-b6ca2a4dc76c';

-- [curatela] secao discussao_medico_legal: {{achados_clinicos_principais}}, {{alteracoes_cognitivas_psiquicas_principais}}, {{atividades_dependentes}}, {{grau_autonomia}}, {{grau_auxilio}}, {{preservacao_comprometimento_capacidade_decisoria}}, {{sintese_capacidade_civil}}
update public.secoes set texto_automatico_template = 'A existência de diagnóstico médico não determina, isoladamente, incapacidade civil. A análise médico-pericial deve estabelecer se as alterações clínicas identificadas repercutem concretamente sobre as capacidades necessárias à compreensão, deliberação, manifestação da vontade, autodeterminação e exercício dos atos da vida civil. No caso em análise, o(a) periciando(a) apresenta {{diagnostico_principal}}, caracterizado por [achados_clinicos_principais], observando-se ao exame [alteracoes_cognitivas_psiquicas_principais]. Do ponto de vista funcional, apresenta [grau_autonomia], necessitando de [grau_auxilio] para [atividades_dependentes]. Quanto à capacidade decisória, verifica-se [preservacao_comprometimento_capacidade_decisoria] da capacidade de compreender informações, avaliar consequências, comparar alternativas, manifestar escolhas e reconhecer riscos relacionados aos atos avaliados. A análise conjunta desses elementos permite estabelecer que [sintese_capacidade_civil]. A eventual indicação de curatela deve ser interpretada de maneira individualizada, proporcional às necessidades concretamente identificadas e com preservação máxima possível da autonomia e da manifestação de vontade do(a) periciando(a).' where id = 'ff1784c0-5149-5836-a94b-9bea1d7cd633';

-- [previdenciario] secao discussao_medico_pericial: {{achados_objetivos_exame}}, {{compatibilidade_atividade}}, {{funcoes_comprometidas}}
update public.secoes set texto_automatico_template = 'A existência de doença ou diagnóstico médico não caracteriza, isoladamente, incapacidade laborativa. No presente caso, o(a) periciando(a) apresenta {{diagnostico_informado}} ({{cid_informado}}), cuja existência encontra-se {{condicao_objetivamente_demonstrada}} pelos elementos documentais e clínicos analisados. Ao exame pericial foram identificados [achados_objetivos_exame], determinando limitações relacionadas a [funcoes_comprometidas]. A atividade habitual de {{profissao_habitual}} demanda {{exigencias_ocupacionais}}. Da correlação entre os achados clínicos, a repercussão funcional e as exigências da atividade, verifica-se [compatibilidade_atividade] entre o estado de saúde atual e o exercício da ocupação habitual. Quando presente incapacidade, esta se caracteriza como {{grau_incapacidade}}, {{duracao_incapacidade}} e {{abrangencia_profissional}}, com capacidade residual {{capacidade_residual}} e possibilidade de reabilitação {{reabilitacao_profissional_indicacao}}.' where id = '59e3d96a-0477-5aa0-90f3-824a366f44cb';

