update public.secoes set texto_automatico_template = 'O(a) periciando(a) apresenta {{diagnostico_informado}}, com achados objetivos caracterizados por [achados_objetivos_exame]. Tais alterações determinam {{repercussao_funcional_objetiva}} de limitação para [funcoes_afetadas], as quais se mostram [compatibilidade_atividade] com as exigências da atividade habitual de {{profissao_habitual}}.' where id = 'a66ceb5a-70bf-5d34-8496-56b659168971';

-- [trabalhista] secao discussao_medico_pericial: {{compatibilidade_temporal}}, {{danos_limitacoes}}, {{diagnostico_cid}}, {{elementos_demonstracao}}, {{exposicoes_ocupacionais_descricao}}, {{fatores_etiologicos_literatura}}, {{fatores_individuais_extralaborais}}, {{impacto_laboral_descricao}}, {{intensidade_frequencia_duracao}}, {{sustenta_ou_nao_sustenta}}
update public.secoes set texto_automatico_template = 'O(a) periciando(a) apresenta [diagnostico_cid], demonstrado por [elementos_demonstracao]. A literatura reconhece como fatores etiológicos [fatores_etiologicos_literatura]. No caso concreto, foram identificadas exposições ocupacionais [exposicoes_ocupacionais_descricao], com intensidade, frequência e duração [intensidade_frequencia_duracao]. A relação temporal entre exposição e adoecimento mostrou-se [compatibilidade_temporal]. Foram ainda identificados [fatores_individuais_extralaborais]. A integração desses elementos [sustenta_ou_nao_sustenta] participação do trabalho na gênese ou agravamento do quadro. As repercussões atuais consistem em [danos_limitacoes], com impacto laboral [impacto_laboral_descricao].' where id = '1a6025d3-4aa4-56ea-827f-f0cc3b7d2342';

