-- [curatela] campo conclusao_modelo_automatico (opções): {{atos_afetados}}, {{dominios_comprometidos}}, {{dominios_preservados}}, {{funcoes_comprometidas}}, {{tipo_complementacao_necessaria}}
update public.campos_secao set opcoes = '[{"codigo": "capacidade_preservada", "rotulo": "Capacidade preservada", "texto_automatico": "Diante dos elementos médico-periciais obtidos, não foram identificadas alterações clínicas, cognitivas ou funcionais de magnitude suficiente para comprometer significativamente a capacidade do(a) periciando(a) de compreender, deliberar e manifestar sua vontade em relação aos atos avaliados, não se evidenciando, sob a perspectiva médico-pericial, necessidade atual de representação ou assistência contínua para atos patrimoniais e negociais."}, {"codigo": "comprometimento_parcial_setorial", "rotulo": "Comprometimento parcial/setorial", "texto_automatico": "O(a) periciando(a) apresenta {{diagnostico_principal}}, com repercussão sobre [funcoes_comprometidas]. Mantém capacidade para [dominios_preservados], porém apresenta prejuízo relevante para [dominios_comprometidos], especialmente quanto a [atos_afetados]. Sob a perspectiva médico-pericial, necessita de apoio/assistência para esses atos específicos, devendo ser preservada sua autonomia nos demais domínios em que demonstra compreensão, discernimento e capacidade de manifestação da vontade."}, {"codigo": "comprometimento_acentuado", "rotulo": "Comprometimento acentuado", "texto_automatico": "O(a) periciando(a) apresenta {{diagnostico_principal}}, associado a comprometimento significativo de [funcoes_comprometidas], com repercussão relevante sobre a capacidade de compreender informações, avaliar consequências, deliberar e administrar autonomamente atos de natureza patrimonial e negocial. Sob a perspectiva médico-pericial, evidencia-se necessidade contínua de proteção e auxílio de terceiros nesses domínios, preservando-se, sempre que possível, sua participação nas decisões e a manifestação de suas preferências e vontade."}, {"codigo": "inconclusivo", "rotulo": "Inconclusivo", "texto_automatico": "Os elementos atualmente disponíveis não permitem estabelecer, com segurança médico-pericial suficiente, a extensão da repercussão da condição clínica sobre a capacidade civil do(a) periciando(a), sendo necessária complementação por [tipo_complementacao_necessaria] antes da emissão de conclusão definitiva."}]'::jsonb where id = '4d18b3ae-374e-5544-9cd5-43073c2c3207';

-- [previdenciario] campo conclusao_modelo_automatico (opções): {{achados_objetivos_exame}}, {{data_periodo_recuperacao_estimada}}, {{evento_causador_sequela}}
update public.campos_secao set opcoes = '[{"codigo": "capacidade_preservada", "rotulo": "Capacidade preservada", "texto_automatico": "O(a) periciando(a) apresenta {{conclusao_diagnostico_principal}}, contudo os achados clínicos objetivos e as repercussões funcionais identificadas na presente avaliação não demonstram limitação de magnitude suficiente para impedir o exercício da atividade habitual de {{profissao_habitual}}. Sob a perspectiva médico-pericial, encontra-se preservada a capacidade laborativa na data do exame."}, {"codigo": "incapacidade_temporaria", "rotulo": "Incapacidade temporária", "texto_automatico": "O(a) periciando(a) apresenta {{conclusao_diagnostico_principal}}, associado a [achados_objetivos_exame], determinando limitações funcionais incompatíveis, no momento, com as exigências da atividade habitual de {{profissao_habitual}}. Caracteriza-se incapacidade laborativa {{conclusao_grau_incapacidade}}, de natureza temporária, com DII estabelecida em {{conclusao_dii}} e recuperação estimada para [data_periodo_recuperacao_estimada], condicionada à evolução clínica e terapêutica."}, {"codigo": "incapacidade_permanente_com_reabilitacao", "rotulo": "Incapacidade permanente com reabilitação", "texto_automatico": "O conjunto dos achados médico-periciais demonstra limitação funcional permanente incompatível com o retorno à atividade habitual de {{profissao_habitual}}. Entretanto, encontram-se preservadas capacidades funcionais que permitem considerar viável a reabilitação profissional para atividade compatível com as restrições identificadas."}, {"codigo": "incapacidade_permanente_sem_reabilitacao", "rotulo": "Incapacidade permanente sem possibilidade de reabilitação", "texto_automatico": "O conjunto dos achados clínicos e funcionais evidencia comprometimento de caráter permanente e extensão suficiente para inviabilizar o desempenho da atividade habitual e de outras atividades compatíveis capazes de garantir subsistência, não se identificando, sob a perspectiva médico-funcional atual, potencial razoável de reabilitação profissional."}, {"codigo": "reducao_permanente_capacidade", "rotulo": "Redução permanente da capacidade", "texto_automatico": "O(a) periciando(a) apresenta sequela consolidada decorrente de [evento_causador_sequela], determinando redução permanente da capacidade para o desempenho da atividade habitualmente exercida, embora permaneça apto(a) ao trabalho mediante maior esforço, adaptação ou redução funcional correspondente às limitações descritas."}]'::jsonb where id = 'ec4bb767-df1e-5eff-996e-61f2dcc1f9dc';

-- [trabalhista] campo conclusao_modelo_automatico (opções): {{atividades_residuais}}, {{condicao}}, {{danos_limitacoes}}, {{descricao_repercussoes}}, {{fator_exposicao}}, {{fatores_nao_laborais}}, {{funcao_exigencias}}, {{restricoes_adaptacoes}}, {{situacao_capacidade}}, {{tarefas_funcao}}, {{tratamento_periodo}}
update public.campos_secao set opcoes = '[{"codigo": "sem_nexo_sem_incapacidade", "rotulo": "Sem nexo e sem incapacidade", "texto_automatico": "O(a) periciando(a) apresenta {{conclusao_diagnostico_principal}}, porém os elementos clínicos, documentais, ocupacionais e etiológicos analisados não demonstram relação causal ou concausal tecnicamente sustentada com o trabalho objeto da demanda. Na data da perícia, não se identificam limitações funcionais de magnitude suficiente para caracterizar incapacidade laborativa."}, {"codigo": "nexo_causal", "rotulo": "Nexo causal", "texto_automatico": "O conjunto médico-pericial demonstra diagnóstico de {{conclusao_diagnostico_principal}}, exposição ocupacional a [fator_exposicao], compatibilidade temporal e biológica e coerência clínico-ocupacional suficientes para estabelecer nexo causal entre o agravo e o trabalho exercido. As repercussões atuais consistem em [danos_limitacoes], com capacidade laborativa [situacao_capacidade]."}, {"codigo": "concausalidade", "rotulo": "Concausalidade", "texto_automatico": "A condição apresenta etiologia multifatorial, com participação de [fatores_nao_laborais]. Entretanto, as condições de trabalho demonstradas atuaram como fator {{papel_trabalho}}, caracterizando concausalidade médico-pericial. As repercussões funcionais atuais são [descricao_repercussoes]."}, {"codigo": "incapacidade_temporaria", "rotulo": "Incapacidade temporária", "texto_automatico": "O(a) periciando(a) apresenta limitação funcional temporária decorrente de [condicao], incompatível atualmente com [funcao_exigencias]. Estima-se necessidade de [tratamento_periodo], devendo a capacidade ser reavaliada conforme evolução clínica."}, {"codigo": "reducao_permanente_capacidade", "rotulo": "Redução permanente da capacidade", "texto_automatico": "Há sequela consolidada com redução funcional permanente para [tarefas_funcao], permanecendo capacidade residual para [atividades_residuais], mediante [restricoes_adaptacoes]."}]'::jsonb where id = '7ad2ef4e-d524-5843-9034-70aa6aed1302';
